package com.example.lrb.service.impl;
import com.example.lrb.dao.NodeDao; import com.example.lrb.enums.NodeEnums; import com.example.lrb.pojo.Node; import com.example.lrb.service.NodeService; import com.example.lrb.vo.JsonResult; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.List;
@Service public class NodeServiceImpl implements NodeService { private final NodeDao dao; public NodeServiceImpl(NodeDao dao){this.dao=dao;} private JsonResult<Node> status(Node n,NodeEnums s,boolean audit){if(n==null||n.getId()==null)return JsonResult.badRequest("笔记ID不能为空");if(audit)n.setAuditStatus(s);else n.setStatus(s);dao.updateByPrimaryKeySelective(n);return JsonResult.ok(n);} public JsonResult<Node> waitingAuthNode(Node n){return status(n,NodeEnums.WAITING_CERTIFICATION,false);} public JsonResult<Node> releasePoem(Node n){return status(n,NodeEnums.AUTHORIZED,false);} public JsonResult<Node> auditReleaseNode(Node n){return status(n,NodeEnums.AUDIT_PASS,true);} public JsonResult<Node> auditDefeatNode(Node n){return status(n,NodeEnums.AUDIT_NO_PASS,true);} public JsonResult<Node> defeatPoem(Node n){return status(n,NodeEnums.DEFEAT_CERTIFICATION,false);} public JsonResult<Node> insert(Node n){n.setCreateTime(LocalDateTime.now());n.setPageview(0);if(n.getAuditStatus()==null)n.setAuditStatus(NodeEnums.WAITING_AUDIT);dao.insertSelective(n);return JsonResult.ok(n);} public JsonResult<List<Node>> listByUserId(Integer id){return JsonResult.ok(dao.queryListByUserId(id));} public JsonResult<List<Node>> listAll(Node n){return JsonResult.ok(dao.queryListAll(n.getUserId(),n.getCategoryId(),n.getTitle(),n.getCity()));} public JsonResult<List<Node>> list(Node n){return JsonResult.ok(dao.queryListByCategoryId(n.getUserId(),n.getCategoryId(),n.getTitle(),n.getCity()));} public JsonResult<Node> query(Integer id,Integer uid){dao.increasePageview(id);Node n=dao.queryById(id,uid);return n==null?JsonResult.notFound("笔记不存在"):JsonResult.ok(n);} public JsonResult<Node> delete(Integer id){Node n=dao.selectByPrimaryKey(id);return dao.deleteByPrimaryKey(id)>0?JsonResult.ok(n):JsonResult.notFound("笔记不存在");} }
